######################
# Compare performance by increasing the dimension of the score mycache matrix: max.parents from 3 to 6 are selected
# Input: "data/n_1000_p_16_nodedists_Balanced_s_02_graph1.Rdata"
# Note params are pre-generated by script `build_score_cache_mle_testfiles.R` and stored in "tests/testthat/testdata/input_score_cache_mle.RData"
# Failing case removed from the computation: child 14, poisson;  parents:     "b1" "g2" "g3" "p1"; function: `/src/irls_poisson_fast.cpp`


source("scripts/setup_score_cache_mle.R")
source("scripts/forLoopContent_refactoring.R")
require(foreach)
library(nnet)
params <- readRDS(file = "tests/testthat/testdata/input_score_cache_mle.RData")
params$max.parents <- unique(params$max.parents)

create_input <- function(mp, params) {
  gc()
  mleparams <- setupScoreCache.mle_orig(data.df = params$data.df[,-c(14)], #params$data.df,
                                        data.dists = params$data.dists[-c(14)], #params$data.dists,
                                        adj.vars = params$adj.vars,
                                        cor.vars = params$cor.vars,
                                        dag.banned = params$dag.banned,
                                        dag.retained = params$dag.retained,
                                        max.parents = mp,
                                        which.nodes = params$which.nodes[-16], #params$which.nodes,
                                        defn.res = params$defn.res,
                                        dry.run = params$dry.run,
                                        verbose = params$verbose,
                                        debugging = params$debugging,
                                        centre = params$centre,
                                        force.method = params$force.method,
                                        group.var = params$group.var,
                                        grouped.vars = params$grouped.vars,
                                        group.ids = params$group.ids,
                                        control = params$control)

  cache_orig = computeCache_orig(params$adj.vars, mleparams$nvars, mleparams$data.df,
                                 mleparams$data.df.lv, mp, params$data.dists[-c(14)])
  return(list(nvars = mleparams$nvars, data.df = mleparams$data.df,
              data.df.multi = mleparams$data.df.multi, data.df.lvl = mleparams$data.df.lvl,
              mp = mp, cache_orig = cache_orig))
}


########################
# Benchmark foreach vs R for loop, using the original forLoopContent function
# - compare results and performance between: foreach (as in the original code), foreach without "combine" option, R for loop

results <- bench::press(
  mp = c(3, 4, 5, 6),
  {
    dat <- create_input(mp, params)
    gc()
    bench::mark(
		orig = call_forLoopContent_orig(params$adj.vars, dat$nvars, dat$data.df,
                                            dat$data.df.multi, dat$data.df.lvl,
                                            dat$mp,
                                            params$data.dists[-c(14)], dat$cache_orig,
                                            params$control, params$verbose),
                foreachrows = call_forLoopContent_foreachrows(params$adj.vars, dat$nvars,mleparams$data.df,
                                            dat$data.df.multi, dat$data.df.lvl,
                                            dat$mp,
                                            params$data.dists[-c(14)], dat$cache_orig,
                                            params$control,params$verbose),
                noforeach = call_forLoopContent_noforeach(params$adj.vars, dat$nvars, dat$data.df,
                                                   dat$data.df.multi, dat$data.df.lvl,
                                                   dat$mp,
                                                   params$data.dists[-c(14)], dat$cache_orig,
                                                   params$control,params$verbose),
                iterations = 1)
  }
)


