######################
# Benchmark the original forLoopContent function against the optimized version (X and Y preallocation)
# - compare results and performance between: the original code, optimized function called within for loop,
# optimized whole function called within a foreach loop


results <- bench::press(
  mp = c(3, 4, 5, 6),
  {
    dat <- create_input(mp, params)
    gc()
    bench::mark(
      orig = call_forLoopContent_orig(params$adj.vars, dat$nvars, dat$data.df,
                                      dat$data.df.multi, dat$data.df.lvl,
                                      dat$mp, params$data.dists[-c(14)], dat$cache_orig,
                                      params$control,params$verbose),
      precomputeXY = call_forLoopContent_precomputedXY(params$adj.vars, dat$nvars, dat$data.df,
                                                       dat$data.df.multi, dat$data.df.lvl,
                                                       dat$mp, params$data.dists[-c(14)], dat$cache_orig,
                                                       params$control,params$verbose),
      precomputeXY_all = call_forLoopContent_precomputedXY_all(params$adj.vars, dat$nvars, dat$data.df,
                                                               dat$data.df.multi, dat$data.df.lvl,
                                                               dat$mp, params$data.dists[-c(14)], dat$cache_orig,
                                                               params$control, params$verbose),

      iterations = 1)
  }
)

